/**
 * Photos are served as resized WebP files generated by scripts/optimise-images.py:
 * '/images/foo.jpeg' -> '/images/foo-800.webp' and '/images/foo-1600.webp'.
 * Code keeps referring to the original photo name; this maps it to the WebP set.
 */
export interface ResponsiveImage {
  src: string
  srcSet: string
}

export function responsiveImage(path: string): ResponsiveImage {
  const base = path.replace(/\.(jpe?g)$/i, '')
  if (base === path) {
    throw new Error(`responsiveImage expects a .jpg or .jpeg path, got "${path}"`)
  }
  const small = `${base}-800.webp`
  const large = `${base}-1600.webp`
  return { src: large, srcSet: `${small} 800w, ${large} 1600w` }
}
